{
  "name": "持久化对象",
  "name_en": "Persistent Object",
  "manufacturer": "",
  "description": "这是一个软件持久化数据模型组件，不是物理实验仪器。它用于实验室软件中保存结构化对象、属性、子项及对象关系，并支持字典读写、UUID 引用、外部数据存取和延迟写入，适合实验数据模型、分析结果和元数据的长期保存。",
  "description_en": "This is a software persistence model component rather than a physical laboratory instrument. It is used in laboratory software to store structured objects, properties, child items, and object relationships, with support for dictionary serialization, UUID references, external data access, and delayed writing. It is suitable for long-term storage of experiment data models, analysis results, and metadata.",
  "tag_hints": [
    "data persistence",
    "object serialization",
    "scientific metadata",
    "UUID references",
    "external data storage",
    "lab data models",
    "delayed write"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭该持久化对象并释放相关资源。",
      "description_en": "Close the persistent object and release related resources."
    },
    {
      "action_name": "auto-deepcopy_from",
      "description": "从另一个对象深拷贝持久化内容。",
      "description_en": "Deep-copy persistent content from another object."
    },
    {
      "action_name": "auto-container",
      "description": "获取该对象所属的容器。",
      "description_en": "Get the container that holds this object."
    },
    {
      "action_name": "auto-insert_model_item",
      "description": "向容器中插入一个模型子项。",
      "description_en": "Insert a model child item into a container."
    },
    {
      "action_name": "auto-remove_model_item",
      "description": "从容器中移除一个模型子项。",
      "description_en": "Remove a model child item from a container."
    },
    {
      "action_name": "auto-about_to_be_inserted",
      "description": "通知对象即将被插入到容器中。",
      "description_en": "Notify the object that it is about to be inserted into a container."
    },
    {
      "action_name": "auto-about_to_be_removed",
      "description": "通知对象即将从容器中移除。",
      "description_en": "Notify the object that it is about to be removed from a container."
    },
    {
      "action_name": "auto-item_specifier",
      "description": "获取该子项的标识说明符。",
      "description_en": "Get the item specifier for this item."
    },
    {
      "action_name": "auto-define_root_context",
      "description": "将该对象定义为根持久化上下文。",
      "description_en": "Define this object as the root persistence context."
    },
    {
      "action_name": "auto-set_storage_system",
      "description": "设置用于持久化的存储系统。",
      "description_en": "Set the storage system used for persistence."
    },
    {
      "action_name": "auto-update_storage_system",
      "description": "从存储中刷新存储系统属性。",
      "description_en": "Refresh storage system properties from storage."
    },
    {
      "action_name": "auto-update_item_context",
      "description": "更新子项上的持久化上下文。",
      "description_en": "Update the persistence context on a child item."
    },
    {
      "action_name": "auto-persistent_object_context",
      "description": "获取或设置持久化对象上下文。",
      "description_en": "Get or set the persistent object context."
    },
    {
      "action_name": "auto-persistent_object_context_changed",
      "description": "通知持久化对象上下文已更改。",
      "description_en": "Notify that the persistent object context has changed."
    },
    {
      "action_name": "auto-persistent_storage",
      "description": "获取或设置持久化存储。",
      "description_en": "Get or set the persistent storage."
    },
    {
      "action_name": "auto-define_type",
      "description": "定义对象类型标识。",
      "description_en": "Define the object type identifier."
    },
    {
      "action_name": "auto-define_property",
      "description": "定义一个持久化属性。",
      "description_en": "Define a persistent property."
    },
    {
      "action_name": "auto-define_item",
      "description": "定义一个持久化子项。",
      "description_en": "Define a persistent child item."
    },
    {
      "action_name": "auto-define_relationship",
      "description": "定义一个持久化对象关系。",
      "description_en": "Define a persistent object relationship."
    },
    {
      "action_name": "auto-close_items",
      "description": "关闭所有子项。",
      "description_en": "Close all child items."
    },
    {
      "action_name": "auto-close_relationships",
      "description": "关闭所有关系项。",
      "description_en": "Close all relationship items."
    },
    {
      "action_name": "auto-undefine_properties",
      "description": "取消定义所有属性。",
      "description_en": "Undefine all properties."
    },
    {
      "action_name": "auto-undefine_items",
      "description": "取消定义所有子项。",
      "description_en": "Undefine all child items."
    },
    {
      "action_name": "auto-undefine_relationships",
      "description": "取消定义所有关系。",
      "description_en": "Undefine all relationships."
    },
    {
      "action_name": "auto-get_storage_properties",
      "description": "获取存储属性的副本。",
      "description_en": "Get a copy of the storage properties."
    },
    {
      "action_name": "auto-property_names",
      "description": "获取已定义属性名称。",
      "description_en": "Get defined property names."
    },
    {
      "action_name": "auto-key_names",
      "description": "获取存储键名称。",
      "description_en": "Get storage key names."
    },
    {
      "action_name": "auto-type",
      "description": "获取对象类型。",
      "description_en": "Get the object type."
    },
    {
      "action_name": "auto-modified",
      "description": "获取对象是否已修改。",
      "description_en": "Get whether the object has been modified."
    },
    {
      "action_name": "auto-modified_count",
      "description": "获取对象修改次数。",
      "description_en": "Get the object's modification count."
    },
    {
      "action_name": "auto-item_names",
      "description": "获取已定义子项名称。",
      "description_en": "Get defined child item names."
    },
    {
      "action_name": "auto-relationship_names",
      "description": "获取已定义关系名称。",
      "description_en": "Get defined relationship names."
    },
    {
      "action_name": "auto-begin_reading",
      "description": "开始从存储中读取对象数据。",
      "description_en": "Begin reading object data from storage."
    },
    {
      "action_name": "auto-read_from_dict",
      "description": "从字典读取对象数据。",
      "description_en": "Read object data from a dictionary."
    },
    {
      "action_name": "auto-finish_reading",
      "description": "完成对象数据读取。",
      "description_en": "Finish reading object data."
    },
    {
      "action_name": "auto-write_to_dict",
      "description": "将对象数据写入字典。",
      "description_en": "Write object data to a dictionary."
    },
    {
      "action_name": "auto-get_item",
      "description": "按名称获取子项。",
      "description_en": "Get a child item by name."
    },
    {
      "action_name": "auto-set_item",
      "description": "按名称设置子项。",
      "description_en": "Set a child item by name."
    },
    {
      "action_name": "auto-load_item",
      "description": "在不更新修改状态的情况下装载子项。",
      "description_en": "Load a child item without updating modification state."
    },
    {
      "action_name": "auto-unload_item",
      "description": "在不更新修改状态的情况下卸载子项。",
      "description_en": "Unload a child item without updating modification state."
    },
    {
      "action_name": "auto-insert_item",
      "description": "向关系中插入一个子项。",
      "description_en": "Insert a child item into a relationship."
    },
    {
      "action_name": "auto-append_item",
      "description": "向关系末尾追加一个子项。",
      "description_en": "Append a child item to a relationship."
    },
    {
      "action_name": "auto-remove_item",
      "description": "从关系中移除一个子项。",
      "description_en": "Remove a child item from a relationship."
    },
    {
      "action_name": "auto-extend_items",
      "description": "向关系中追加多个子项。",
      "description_en": "Append multiple child items to a relationship."
    },
    {
      "action_name": "auto-item_count",
      "description": "获取关系中的子项数量。",
      "description_en": "Get the number of items in a relationship."
    },
    {
      "action_name": "auto-item_index",
      "description": "获取子项在关系中的索引。",
      "description_en": "Get the index of an item within a relationship."
    },
    {
      "action_name": "auto-get_item_by_uuid",
      "description": "按 UUID 获取关系中的子项。",
      "description_en": "Get a relationship item by UUID."
    },
    {
      "action_name": "auto-change_relationship_item_uuid",
      "description": "修改关系中子项的 UUID。",
      "description_en": "Change the UUID of a relationship item."
    },
    {
      "action_name": "auto-get_relationship_items",
      "description": "获取关系中的所有子项。",
      "description_en": "Get all items in a relationship."
    },
    {
      "action_name": "auto-item_set",
      "description": "通知已设置指定名称的子项。",
      "description_en": "Notify that a named item has been set."
    },
    {
      "action_name": "auto-property_changed",
      "description": "通知某个属性值已更改。",
      "description_en": "Notify that a property value has changed."
    },
    {
      "action_name": "auto-clear_property",
      "description": "清除指定属性值。",
      "description_en": "Clear a specified property value."
    },
    {
      "action_name": "auto-read_external_data",
      "description": "按名称读取外部存储数据。",
      "description_en": "Read externally stored data by name."
    },
    {
      "action_name": "auto-write_external_data",
      "description": "按名称写入外部数据。",
      "description_en": "Write external data by name."
    },
    {
      "action_name": "auto-reserve_external_data",
      "description": "为外部数据预留存储空间。",
      "description_en": "Reserve storage space for external data."
    },
    {
      "action_name": "auto-enter_write_delay",
      "description": "启用延迟写入模式。",
      "description_en": "Enable delayed-write mode."
    },
    {
      "action_name": "auto-exit_write_delay",
      "description": "退出延迟写入模式。",
      "description_en": "Disable delayed-write mode."
    },
    {
      "action_name": "auto-is_write_delayed",
      "description": "获取是否处于延迟写入状态。",
      "description_en": "Get whether delayed writing is enabled."
    },
    {
      "action_name": "auto-rewrite",
      "description": "将延迟的更改重新写入存储。",
      "description_en": "Write delayed changes back to storage."
    },
    {
      "action_name": "auto-create_item_proxy",
      "description": "创建子项代理。",
      "description_en": "Create an item proxy."
    },
    {
      "action_name": "auto-create_item_reference",
      "description": "创建子项引用。",
      "description_en": "Create an item reference."
    },
    {
      "action_name": "auto-destroy_item_reference",
      "description": "销毁子项引用。",
      "description_en": "Destroy an item reference."
    },
    {
      "action_name": "auto-resolve_item_specifier",
      "description": "解析子项说明符并定位对象。",
      "description_en": "Resolve an item specifier to an object."
    },
    {
      "action_name": "auto-lookup_id",
      "description": "按标识符查找对象。",
      "description_en": "Look up an object by identifier."
    }
  ]
}

